import{_ as r,o as d,c as a,a2 as e}from"./chunks/framework.wVcpyw2-.js";const u=JSON.parse('{"title":"编辑器界面说明","description":"编辑器界面说明：灵萌 功能开启官方文档，面向站点管理员与运营人员，含配置步骤与注意事项。","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/interface.md","filePath":"features/ui-editor/interface.md","lastUpdated":1785051348000}'),o={name:"features/ui-editor/interface.md"};function n(s,t,h,i,l,g){return d(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="编辑器界面说明" tabindex="-1">编辑器界面说明 <a class="header-anchor" href="#编辑器界面说明" aria-label="Permalink to &quot;编辑器界面说明&quot;">​</a></h1><p>路径：<strong>UI管理 → 页面配置</strong> → 进入某页面的 <strong>设计</strong> 界面。</p><h2 id="整体布局" tabindex="-1">整体布局 <a class="header-anchor" href="#整体布局" aria-label="Permalink to &quot;整体布局&quot;">​</a></h2><h3 id="电脑宽屏" tabindex="-1">电脑宽屏 <a class="header-anchor" href="#电脑宽屏" aria-label="Permalink to &quot;电脑宽屏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>区域</th><th>功能</th></tr></thead><tbody><tr><td><strong>顶栏工具栏</strong></td><td>返回、撤销/重做、清空、导入导出、预览、保存</td></tr><tr><td><strong>左侧组件库</strong></td><td>按分类展示可添加的组件，点击即插入画布</td></tr><tr><td><strong>中间画布</strong></td><td>750rpx 宽手机预览框，含状态栏与导航栏模拟</td></tr><tr><td><strong>右侧属性面板</strong></td><td>「属性」「样式」两个 Tab；未选中组件时为页面配置</td></tr><tr><td><strong>AI 面板</strong>（可选）</td><td>右侧或独立栏，描述需求生成布局</td></tr></tbody></table><h3 id="手机管理端" tabindex="-1">手机管理端 <a class="header-anchor" href="#手机管理端" aria-label="Permalink to &quot;手机管理端&quot;">​</a></h3><p>底部四个 Tab 切换：<strong>组件 | 画布 | AI | 属性</strong>，功能与宽屏一致。</p><h2 id="顶栏工具栏" tabindex="-1">顶栏工具栏 <a class="header-anchor" href="#顶栏工具栏" aria-label="Permalink to &quot;顶栏工具栏&quot;">​</a></h2><table tabindex="0"><thead><tr><th>按钮</th><th>作用</th></tr></thead><tbody><tr><td><strong>返回</strong></td><td>回到页面配置列表（未保存会提示）</td></tr><tr><td><strong>撤销 / 重做</strong></td><td>回退或恢复编辑操作</td></tr><tr><td><strong>清空</strong></td><td>删除画布上全部组件（需确认）</td></tr><tr><td><strong>导出 JSON</strong></td><td>下载当前页面配置，用于备份或迁移</td></tr><tr><td><strong>导入 JSON</strong></td><td>从文件恢复布局（覆盖当前画布）</td></tr><tr><td><strong>预览</strong></td><td>截取手机框截图，弹层查看效果（不发布）</td></tr><tr><td><strong>保存</strong></td><td>写入服务器；可选更新列表封面图</td></tr></tbody></table><h2 id="画布操作" tabindex="-1">画布操作 <a class="header-anchor" href="#画布操作" aria-label="Permalink to &quot;画布操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>方法</th></tr></thead><tbody><tr><td>选中组件</td><td>点击画布上的组件块</td></tr><tr><td>取消选中</td><td>点击画布空白或导航栏下方空白</td></tr><tr><td>调整顺序</td><td>选中后使用 <strong>上移 / 下移</strong></td></tr><tr><td>复制</td><td><strong>复制</strong> 生成一份相同配置的组件</td></tr><tr><td>删除</td><td><strong>删除</strong> 移除该组件</td></tr></tbody></table><p>选中时组件周围有高亮边框，右侧同步显示其属性。</p><h2 id="右侧属性面板" tabindex="-1">右侧属性面板 <a class="header-anchor" href="#右侧属性面板" aria-label="Permalink to &quot;右侧属性面板&quot;">​</a></h2><h3 id="未选中组件时-—-页面配置" tabindex="-1">未选中组件时 — 页面配置 <a class="header-anchor" href="#未选中组件时-—-页面配置" aria-label="Permalink to &quot;未选中组件时 — 页面配置&quot;">​</a></h3><p>根据页面类型不同，面板标题为 <strong>页面配置</strong>、<strong>圈子配置</strong> 或 <strong>服务表单</strong>：</p><p><strong>通用页面配置</strong>（首页、自定义页等）：</p><table tabindex="0"><thead><tr><th>分组</th><th>可配置项</th></tr></thead><tbody><tr><td>页面背景</td><td>背景颜色</td></tr><tr><td>顶部背景图</td><td>图片、背景图高度</td></tr><tr><td>导航栏</td><td>是否显示标题/返回按钮、标题文字与对齐、导航栏样式（默认/胶囊/自定义/无）</td></tr><tr><td>胶囊导航</td><td>胶囊颜色、圆角、阴影等（选胶囊样式时）</td></tr><tr><td>分享</td><td>分享标题、分享图片</td></tr></tbody></table><p><strong>圈子页</strong> 额外有头区布局、动态列表是否跟随首页等，见 <a href="/features/ui-editor/page-types#社区圈子-forum">页面类型 — 社区圈子</a>。</p><p><strong>服务表单页</strong> 额外有履约模式、计价公式等，见 <a href="/features/ui-editor/page-types#服务表单-errand_service">页面类型 — 服务表单</a>。</p><h3 id="选中组件时" tabindex="-1">选中组件时 <a class="header-anchor" href="#选中组件时" aria-label="Permalink to &quot;选中组件时&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tab</th><th>内容</th></tr></thead><tbody><tr><td><strong>属性</strong></td><td>该组件的业务内容（文案、图片、数据源、跳转等）</td></tr><tr><td><strong>样式</strong></td><td>尺寸、内外边距、背景、圆角、边框、透明度、阴影</td></tr></tbody></table><p>列表 section 类组件有特殊说明，见 <a href="/features/ui-editor/styles-and-actions#列表-section-的样式分层">样式与点击动作</a>。</p><h2 id="左侧组件库" tabindex="-1">左侧组件库 <a class="header-anchor" href="#左侧组件库" aria-label="Permalink to &quot;左侧组件库&quot;">​</a></h2><p>组件按 6 大类折叠展示：</p><ul><li>基础元素、布局导航、信息展示、社区内容、运营模块、表单/服务</li></ul><p><strong>灰色不可点</strong> 的组件表示当前页面类型不允许使用（例如首页不能添加表单组件）。</p><p><strong>圈子页</strong> 左侧还会出现 <strong>头区布局</strong>、<strong>笔记卡片模板</strong> 等圈子专属配置项，不属于画布组件。</p><h2 id="页面列表面板" tabindex="-1">页面列表面板 <a class="header-anchor" href="#页面列表面板" aria-label="Permalink to &quot;页面列表面板&quot;">​</a></h2><p>在 <strong>UI管理 → 页面配置</strong> 列表页：</p><table tabindex="0"><thead><tr><th>元素</th><th>说明</th></tr></thead><tbody><tr><td>封面图</td><td>保存时生成的截图；无图时显示占位</td></tr><tr><td>类型标签</td><td>首页 / 功能页 / 自定义页 等</td></tr><tr><td>状态</td><td><strong>启用</strong>（绿色）或 <strong>禁用</strong></td></tr><tr><td><strong>设计</strong></td><td>进入可视化编辑器</td></tr><tr><td><strong>启用 / 禁用</strong></td><td>切换对用户生效的版本</td></tr><tr><td><strong>复制</strong></td><td>复制为新的配置草稿</td></tr><tr><td><strong>删除</strong></td><td>删除该条配置</td></tr></tbody></table><p>顶部 <strong>区域筛选</strong> 决定当前列表与新建页面所属区域。</p><h2 id="导入导出使用场景" tabindex="-1">导入导出使用场景 <a class="header-anchor" href="#导入导出使用场景" aria-label="Permalink to &quot;导入导出使用场景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>做法</th></tr></thead><tbody><tr><td>测试环境 → 生产环境</td><td>测试环境导出 JSON，生产环境同类型页面导入</td></tr><tr><td>备份</td><td>重大改版前导出一份 JSON 存档</td></tr><tr><td>多区域快速复用</td><td>平台默认导出 → 目标区域新建同类型 → 导入 → 微调 → 启用</td></tr></tbody></table><p>导入会 <strong>覆盖</strong> 当前画布全部内容，操作前请确认或先导出备份。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/features/ui-editor/page-types">页面类型说明</a></li><li><a href="/features/ui-editor/styles-and-actions">样式与点击动作</a></li><li><a href="/features/ui-editor/components-basic">组件手册</a></li></ul>',36)])])}const c=r(o,[["render",n]]);export{u as __pageData,c as default};
